import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const root='Bomberman-Ultimate-Universal-Web-v0.10/files/';
const source=name=>fs.readFileSync(root+name,'utf8');
function setup(){
 let clock=10000;
 const c={console,Date:class extends Date{static now(){return clock}},Math,location:{search:'?netdebug=1'},S:{role:'offline'},createjs:{Ticker:{getMeasuredFPS:()=>50}}};c.window=c;
 c.Player={extend:o=>{function Bot(){}Bot.prototype=o;return Bot}};
 c.gGameEngine={tileSize:50,tilesX:19,tilesY:15,tiles:[],bombs:[],bonuses:[],bots:[],players:[],playing:true,menu:{visible:false},fps:50,ultimateMode:false,getTileMaterial(p){if(p.x<=0||p.y<=0||p.x>=this.tilesX-1||p.y>=this.tilesY-1)return'wall';return this.tiles.find(t=>t.position.x===p.x&&t.position.y===p.y)?.material||'grass'},getPlayersAndBots(){return this.players.concat(this.bots)}};
 vm.createContext(c);vm.runInContext(source('js/Utils.js'),c);vm.runInContext(source('js/Bot.js'),c);
 vm.runInContext(`function G(){return gGameEngine} function same(a,b){return !!(a&&b&&a.x===b.x&&a.y===b.y)} function key(p){return p?p.x+','+p.y:''} function clean(s){return String(s||'')} function hash(s){var h=0;for(var i=0;i<String(s).length;i++)h=(h*31+String(s).charCodeAt(i))>>>0;return h} function pos(k){var a=k.split(',');return {x:+a[0],y:+a[1]}}`,c);
 // Real historical controller code, in production order. Render/UI is not needed here.
 function layer(file,start,end,install){const s=source(file);vm.runInContext(`(function(){var ratingOverride=0;${s.slice(s.indexOf(start),s.indexOf(end))};${install}})();`,c)}
 layer('runtime-v0134-gameplay.js','function G()','function kindOf(','patchAI();window.oldReservations=resolveReservations;window.BomberGameplay134={tryBaitTrap:tryBaitTrap};');
 layer('runtime-v0135-polish.js','function G()','function syncEntityName(','patchAI()');
 layer('runtime-v0136-challenge.js','function G()','function appearanceFor(','patchAI()');
 layer('runtime-v0137-stability.js','function key(p)','\nfunction install(){','patchAI()');
 layer('runtime-v0138-ai-social.js','/* Movement governor:','/* Social personality layer.','patchMovement();window.BomberAI138={ensureSpeed:ensureSpeed,watchdog:watchdog};');
 const latest=source('runtime-v0140-stability-social.js').includes('/* Single AI movement owner.');
 layer('runtime-v0140-stability-social.js',latest?'/* Single AI movement owner.':'/* Movement governor:','/* One visible owner','patchMovement();window.control={motion,sample,corridorProblem,forceNovelRoute,hardRecover,watchdog,strictItemAmbush,escapeDisposition,ensureSpeed:window.BomberMovementController?ensureSpeed:BomberAI138.ensureSpeed};');
 function bot(x,y){const b=Object.create(c.Bot.prototype);Object.assign(b,{position:{x,y},bmp:{x:x*50,y:y*50},targetPosition:{x,y},targetBitmapPosition:{x:x*50,y:y*50},velocity:2.4,v125Difficulty:'hard',alive:true,started:true,bombs:[],bombsMax:0,bombStrength:2,escapeMode:false,hyperAggressive:false,hyperAggroSpeedApplied:false,animate(){},handleBonusCollision(){},detectFireCollision(){return false},updatePosition(){this.position=c.Utils.convertToEntityPosition(this.bmp)},detectWallCollision(p){return c.gGameEngine.getTileMaterial(c.Utils.convertToEntityPosition(p))!=='grass'},detectBombCollision(){return false},remainingWoodCount(){return 0},updateEndgameAggression(){},displayName:'Bot'});c.gGameEngine.bots.push(b);return b}
 function frames(n){for(let i=0;i<n;i++){clock+=20;for(const b of c.gGameEngine.bots)if(b.alive)b.update();if(i%7===0)c.oldReservations();if(i%6===0)for(const b of c.gGameEngine.bots)c.BomberAI138.watchdog(b)}}
 return {c,g:c.gGameEngine,bot,frames,tick:ms=>clock+=ms};
}
let count=0,failed=0;function test(name,fn){try{fn();count++;console.log('PASS',name)}catch(e){failed++;console.error('FAIL',name,e.stack)}}
test('pixel steering reaches rounded tile center without zero direction',()=>{const {bot,frames}=setup();const b=bot(5,5);b.bmp.x=232;b.setNextTile({x:5,y:5});assert.equal(b.dirX,1);b.chooseNextAction=()=>{};frames(20);assert.equal(b.bmp.x,250);assert.equal(b.bmp.y,250)});
test('mid-tile perpendicular target centers before turning',()=>{const {bot,frames}=setup();const b=bot(5,5);b.bmp.x=232;b.setNextTile({x:5,y:6});b.chooseNextAction=()=>{};frames(80);assert.equal(b.bmp.x,250);assert.equal(b.bmp.y,300)});
test('old timer cannot redirect overlapping escape',()=>{const {c,bot}=setup();const a=bot(4,4),b=bot(4,4);a.escapeMode=true;a.setNextTile({x:5,y:4});b.setNextTile({x:4,y:5});c.oldReservations();assert.equal(a.targetPosition.x,5);assert.equal(a.targetPosition.y,4)});
test('stacked bots independently recover and physically separate',()=>{const {c,bot,frames}=setup();const a=bot(8,6),b=bot(8,6);c.control.hardRecover(a,'stuck');c.control.hardRecover(b,'stuck');assert.notEqual(JSON.stringify(c.control.motion(a).route),JSON.stringify(c.control.motion(b).route));frames(100);assert.ok(Math.hypot(a.bmp.x-b.bmp.x,a.bmp.y-b.bmp.y)>40)});
for(const axis of ['horizontal','vertical'])test('long '+axis+' shuttle commits to multi-tile exit',()=>{const {c,g,bot,frames}=setup();const b=bot(axis==='horizontal'?14:5,axis==='horizontal'?5:12),m=c.control.motion(b),h=[];for(let x=1;x<=14;x++)h.push(axis==='horizontal'?x+',5':'5,'+x);for(let x=13;x>=1;x--)h.push(axis==='horizontal'?x+',5':'5,'+x);for(let x=2;x<=14;x++)h.push(axis==='horizontal'?x+',5':'5,'+x);m.trail=h;assert.equal(c.control.corridorProblem(b),axis);assert.ok(c.control.forceNovelRoute(b,axis));const route=m.route;assert.ok(route.length>=2);assert.ok(axis==='horizontal'?Math.abs(route.at(-1).y-5)>=2:Math.abs(route.at(-1).x-5)>=2);g.players=[{alive:true,position:{x:1,y:1}}];frames(45);assert.ok(axis==='horizontal'?Math.abs(b.position.y-5)>=2:Math.abs(b.position.x-5)>=2)});
test('one reversal is permitted',()=>{const {c,bot}=setup();const b=bot(2,5);c.control.motion(b).trail=['1,5','2,5','3,5','4,5','5,5','4,5','3,5','2,5'];assert.equal(c.control.corridorProblem(b),'')});
test('minor lane detour still detects repeating axis',()=>{const {c,bot}=setup();const b=bot(3,6);c.control.motion(b).trail=['1,5','2,5','3,5','4,5','5,5','5,6','4,6','3,6','2,6','1,6','2,6'];assert.equal(c.control.corridorProblem(b),'horizontal')});
test('pixel jitter and intent churn do not reset progress',()=>{const {c,bot,tick}=setup();const b=bot(5,5),m=c.control.motion(b),at=m.lastMovedAt;for(let i=0;i<20;i++){tick(100);b.bmp.x=250+(i%2);b.targetPosition={x:5+i%2,y:5};c.control.sample(b)}assert.equal(m.lastMovedAt,at);assert.equal(c.control.watchdog(b),'stuck')});
test('real bomb-cover wait survives watchdog',()=>{const {c,g,bot,tick}=setup();const b=bot(5,5),bomb={position:{x:2,y:2},exploded:false,getDangerPositions:()=>[{x:2,y:2}]};g.bombs=[bomb];b.beginEscapePlan([{x:4,y:5},{x:5,y:5}],bomb);b.escapePathIndex=2;const m=c.control.motion(b);tick(2200);assert.equal(c.control.watchdog(b),'');assert.equal(b.escapeMode,true);assert.equal(m.hardResets,0)});
test('stale escape cannot immunize an immobile bot',()=>{const {c,bot,tick,frames}=setup();const b=bot(5,5);b.beginEscapePlan([{x:4,y:5},{x:5,y:5}],{});b.escapePathIndex=2;c.control.motion(b);tick(2000);assert.equal(c.control.watchdog(b),'escape-stale');assert.equal(b.escapeMode,false);frames(30);assert.ok(b.bmp.x!==250||b.bmp.y!==250)});
test('new bomb preempts route with timed escape',()=>{const {c,g,bot}=setup();const b=bot(5,5);c.control.forceNovelRoute(b,'stuck');g.bombs=[{position:{x:4,y:5},timerMax:2,timer:0,exploded:false,getDangerPositions:()=>[{x:4,y:5},{x:5,y:5},{x:6,y:5}]}];b.chooseNextAction();assert.equal(b.escapeMode,true);assert.ok(b.escapePath.length>1);assert.equal(c.control.motion(b).route,null)});
test('early-game powerups remain objectives',()=>{const {g,bot}=setup();const b=bot(5,5);b.remainingWoodCount=()=>50;g.bonuses=[{position:{x:5,y:7},type:'speed'}];b.chooseNextAction();assert.equal(b.targetPosition.x,5);assert.equal(b.targetPosition.y,6)});
test('late-game bot hunts human despite powerup',()=>{const {g,bot,frames}=setup();const b=bot(3,3);g.players=[{alive:true,position:{x:12,y:9}}];g.bonuses=[{position:{x:1,y:1},type:'speed'}];assert.equal(b.getBestOpponent(),g.players[0]);assert.equal(b.getBestBonusPath(),null);frames(160);assert.ok(Math.abs(b.position.x-12)+Math.abs(b.position.y-9)<15)});
test('difficulty and earned shoes survive speed corruption',()=>{const {c,bot}=setup();for(const [d,base] of Object.entries({easy:1.55,normal:2,hard:2.4,expert:2.75})){const b=bot(3,3);b.v125Difficulty=d;b.velocity=.02;b.__v138Shoes=3;assert.ok(Math.abs(c.control.ensureSpeed(b)-(base+2.4))<1e-9)}});
test('guest watchdogs do not mutate replicated actors',()=>{const {c,bot,tick}=setup();const b=bot(3,3);c.S.role='guest';const before=JSON.stringify(b);tick(4000);c.control.watchdog(b);c.BomberAI138.watchdog(b);c.oldReservations();assert.equal(JSON.stringify(b),before)});
test('item trap is useful safe and bounded',()=>{const {c,g,bot,tick}=setup();const b=bot(5,5);b.simulatedHuman=true;b.__v134Bait={x:6,y:5,ambush:{x:5,y:5},created:c.Date.now()};g.bonuses=[{position:{x:6,y:5}}];g.players=[{alive:true,position:{x:7,y:5}}];assert.equal(c.control.strictItemAmbush(b),true);tick(4100);assert.equal(c.control.strictItemAmbush(b),false)});
console.log(`AI_CONTROLLER_REGRESSION ${count} passed, ${failed} failed`);if(failed)process.exitCode=1;
